package com.luatweaker.common.content;

import com.luatweaker.api.content.IContentService;
import com.luatweaker.api.content.IDatapackService;
import com.luatweaker.api.content.IFluidBuilder;
import com.luatweaker.api.log.LogStage;
import com.luatweaker.common.util.CallbackFirewall;
import org.jetbrains.annotations.NotNull;

/**
 * Writes loader-agnostic fluid assets (texture animation metadata, fluid
 * blockstates, particle-only block models). The bucket item models use a
 * loader-specific model loader and are generated by each platform module.
 */
final class ContentFluidAssets {

    private ContentFluidAssets() {
    }

    static void rebuild(@NotNull IContentService contentService, @NotNull IDatapackService datapackService) {
        for (IFluidBuilder builder : contentService.getRegisteredFluids()) {
            CallbackFirewall.run(() -> injectFluidAsset(datapackService, builder), LogStage.SYSTEM,
                    () -> "[ContentFluidAssets] Failed fluid assets for '" + builder.getId() + "'");
        }
    }

    private static void injectFluidAsset(@NotNull IDatapackService datapackService,
                                         @NotNull IFluidBuilder builder) {
        String[] parts = ContentAssetPaths.parseId(builder.getId());
        String namespace = parts[0];
        String id = parts[1];
        String blockId = id + "_block";

        String stillTexture = builder.getStillTexture() != null
                ? builder.getStillTexture()
                : "minecraft:block/water_still";
        String animationMetadata = "{\n  \"animation\": {\n    \"frametime\": 2\n  }\n}";
        if (builder.getStillTexture() != null) {
            datapackService.addData(fluidTextureMcmetaKey(builder.getStillTexture()), animationMetadata);
        }
        if (builder.getFlowingTexture() != null) {
            datapackService.addData(fluidTextureMcmetaKey(builder.getFlowingTexture()), animationMetadata);
        }

        String blockstateJson = "{\n  \"variants\": {\n    \"\": { \"model\": \"" + namespace
                + ContentAssetPaths.BLOCK_MODEL_PREFIX + id + "\" }\n  }\n}";
        datapackService.addData(ContentAssetPaths.ASSETS_PREFIX + namespace
                + ContentAssetPaths.BLOCKSTATES_DIR + id + ContentAssetPaths.JSON_EXTENSION, blockstateJson);
        datapackService.addData(ContentAssetPaths.ASSETS_PREFIX + namespace
                + ContentAssetPaths.BLOCKSTATES_DIR + blockId + ContentAssetPaths.JSON_EXTENSION, blockstateJson);

        String blockModelJson = "{\n  \"textures\": {\n    \"particle\": \"" + stillTexture
                + ContentAssetPaths.JSON_TAIL;
        datapackService.addData(ContentAssetPaths.ASSETS_PREFIX + namespace
                + ContentAssetPaths.MODELS_BLOCK_DIR + id + ContentAssetPaths.JSON_EXTENSION, blockModelJson);
        datapackService.addData(ContentAssetPaths.ASSETS_PREFIX + namespace
                + ContentAssetPaths.MODELS_BLOCK_DIR + blockId + ContentAssetPaths.JSON_EXTENSION, blockModelJson);

        String bucketId = id + "_bucket";
        String bucketKey = ContentAssetPaths.ASSETS_PREFIX + namespace
                + ContentAssetPaths.MODELS_ITEM_DIR + bucketId + ContentAssetPaths.JSON_EXTENSION;
        if (!datapackService.hasData(bucketKey)) {
            String bucketJson = "{\n"
                    + "  \"parent\": \"minecraft:item/generated\",\n"
                    + "  \"textures\": {\n"
                    + "    \"layer0\": \"minecraft:item/bucket\"\n"
                    + "  }\n"
                    + "}";
            datapackService.addData(bucketKey, bucketJson);
        }
    }

    private static String fluidTextureMcmetaKey(@NotNull String textureId) {
        String[] parts = ContentAssetPaths.parseId(textureId);
        return ContentAssetPaths.ASSETS_PREFIX + parts[0] + "/textures/block/"
                + parts[1].replace("block/", "") + ".png.mcmeta";
    }
}
